    'tst.46': ['{name} artık {role}.', '{name} is now {role}.'], 'tst.47': ['{name} kulüpten çıkarıldı.', '{name} was removed from the club.'], 'tst.48': ['Etkinlik iptal edildi. Katılımcılara haber verildi.', 'Event cancelled. Attendees were notified.'], 'tst.49': ['Başkanlık {name} kullanıcısına devredildi.', 'Presidency transferred to {name}.'], 'tst.50.suspended': ['Kulüp askıya alındı.', 'Club suspended.'], 'tst.50.activated': ['Kulüp yeniden etkinleştirildi.', 'Club reactivated.'],
    'tst.51': ['İçerik kaldırıldı.', 'Content removed.'], 'tst.52.suspended': ['Kullanıcı askıya alındı.', 'User suspended.'], 'tst.52.unsuspended': ['Kullanıcının askısı kaldırıldı.', 'User unsuspended.'], 'tst.53.pinned': ['Gönderi sabitlendi.', 'Post pinned.'], 'tst.53.unpinned': ['Sabitleme kaldırıldı.', 'Post unpinned.'], 'tst.54.opened': ['Başvurular açıldı.', 'Applications opened.'], 'tst.54.closed': ['Başvurular kapatıldı.', 'Applications closed.'], 'tst.55': ['Yeni bildirim: {title}', 'New notification: {title}'],
